430	// recordSemanticProblems は必須キー・列挙値・参照の整合を検査する。
431	func recordSemanticProblems(f string, doc *recordDoc) []string {
432		var problems []string
433		add := func(format string, args ...any) {
434			problems = append(problems, f+": "+fmt.Sprintf(format, args...))
435		}
436		if len(doc.Runs) == 0 {
437			add("runs がありません (実行が 1 つも無い)")
438		}
439		// 回ごとの問題 id の索引 (plan_ref の解決と被覆の検査に使う)。
440		plansByRun := make([]map[string]bool, len(doc.Runs))
441		for ri, run := range doc.Runs {
442			plansByRun[ri] = map[string]bool{}
443			for _, pl := range run.Plans {
444				plansByRun[ri][pl.ProblemID] = true
445			}
446		}
447		for ri, run := range doc.Runs {
448			rn := fmt.Sprintf("runs[%d] (%s %s)", ri, run.Date, run.Skill)
449			if !recordDateRe.MatchString(run.Date) {
450				add("%s: date が YYYY-MM-DD ではありません: %q", rn, run.Date)
451			}
452			if run.Skill == "" {
453				add("%s: skill がありません", rn)
454			}
455			if run.Model == "" {
456				add("%s: model がありません (レビューを実行したモデルを必ず残す)", rn)
457			}
458			if run.Scope != "incremental" && run.Scope != "full" {
459				add("%s: scope は incremental / full のいずれか: %q", rn, run.Scope)
460			}
461			if run.Head == "" {
462				add("%s: head がありません (レビュー時点の短縮 SHA)", rn)
463			}
464	
465			verdictByID := map[int]string{}
466			for fi, fd := range run.Findings {
467				fn := fmt.Sprintf("%s: findings[%d] (id %d)", rn, fi, fd.ID)
468				if fd.ID <= 0 {
469					add("%s: id は正の整数にする", fn)
470				} else if _, dup := verdictByID[fd.ID]; dup {
471					add("%s: id が同じ回の中で重複しています", fn)
472				}
473				verdictByID[fd.ID] = fd.Verdict
474				for _, kv := range []struct{ key, val string }{
475					{"file", fd.File}, {"summary", fd.Summary},
476					{"category", fd.Category}, {"audience", fd.Audience},
477				} {
478					if kv.val == "" {
479						add("%s: %s がありません", fn, kv.key)
480					}
481				}
482				// audience の列挙。列挙外の値が黙って通ると D7 (被害者の判定) の入力が壊れる。
483				if fd.Audience != "" && !recordAudiences[fd.Audience] {
484					add("%s: audience は operator / admin / provider / developer のいずれか: %q", fn, fd.Audience)
485				}
486				if fd.AudienceInitial != "" && !recordAudiences[fd.AudienceInitial] {
487					add("%s: audience_initial は operator / admin / provider / developer のいずれか: %q", fn, fd.AudienceInitial)
488				}
489				for _, kv := range []struct{ key, val string }{
490					{"condition", fd.Consequence.Condition}, {"who", fd.Consequence.Who},
491					{"what", fd.Consequence.What}, {"detectability", fd.Consequence.Detectability},
492				} {
493					if kv.val == "" {
494						add("%s: consequence.%s がありません (帰結の 4 項目は必須)", fn, kv.key)
495					}
496				}
497				switch fd.PremiseCheck.Stages {
498				case "none", "A", "A+B":
499				default:
500					add("%s: premise_check.stages は none / A / A+B のいずれか: %q", fn, fd.PremiseCheck.Stages)
501				}
502				switch fd.PremiseCheck.Result {
503				case "verified", "wrong", "unverifiable", "skipped":
504				default:
505					add("%s: premise_check.result は verified / wrong / unverifiable / skipped のいずれか: %q",
506						fn, fd.PremiseCheck.Result)
507				}
508				if (fd.PremiseCheck.Stages == "none") != (fd.PremiseCheck.Result == "skipped") {
509					add("%s: stages が none のときだけ result は skipped (stages %q / result %q)",
510						fn, fd.PremiseCheck.Stages, fd.PremiseCheck.Result)
511				}
512				switch fd.Verdict {
513				case "adopted", "held", "rejected":
514				default:
515					add("%s: verdict は adopted / held / rejected のいずれか: %q", fn, fd.Verdict)
516				}
517				if fd.VerdictReason == "" {
518					add("%s: verdict_reason がありません (判定の経路をノード ID で書く)", fn)
519				}
520				if fd.PlanRef != nil {
521					if fd.PlanRef.Run < 1 || fd.PlanRef.Run > len(doc.Runs) {
522						add("%s: plan_ref の run %d は存在しません (回は 1〜%d)", fn, fd.PlanRef.Run, len(doc.Runs))
523					} else if !plansByRun[fd.PlanRef.Run-1][fd.PlanRef.Problem] {
524						add("%s: plan_ref の問題 %q は回 %d の plans にありません", fn, fd.PlanRef.Problem, fd.PlanRef.Run)
525					}
526				}
527			}
528	
529			problemIDs := map[string]bool{}
530			for _, pl := range run.Plans {
531				if pl.ProblemID != "" && problemIDs[pl.ProblemID] {
532					add("%s: problem_id %q が重複しています", rn, pl.ProblemID)
533				}
534				problemIDs[pl.ProblemID] = true
535			}
536			for pi, pl := range run.Plans {
537				pn := fmt.Sprintf("%s: plans[%d] (%s)", rn, pi, pl.ProblemID)
538				for _, kv := range []struct{ key, val string }{
539					{"problem_id", pl.ProblemID}, {"cause", pl.Cause}, {"approach", pl.Approach},
540				} {
541					if kv.val == "" {
542						add("%s: %s がありません", pn, kv.key)
543					}
544				}
545				if len(pl.FindingIDs) == 0 {
546					add("%s: finding_ids がありません (1 つ以上)", pn)
547				}
548				for _, id := range pl.FindingIDs {
549					v, ok := verdictByID[id]
550					if !ok {
551						add("%s: finding_ids の %d は同じ回の findings にありません", pn, id)
552					} else if v != "adopted" {
553						add("%s: finding_ids の %d は採択 (adopted) ではありません (verdict %s)。修正計画は採択だけを束ねる", pn, id, v)
554					}
555				}
556				// externalOnly は done-external 専用のキーが空であることを検査する。
557				// スキーマ表が「done-external のときだけ書く」と定める排他で、書かせる
558				// だけで検査しないと、done でコミット済みなのに外部 URL が残る記録が
559				// 黙って通る (sha の排他は前から検査されていた)。列挙外の status では
560				// 呼ばない — default が列挙違反を報告するので、そこへ重ねると 1 つの
561				// 誤字が 2 つの問題になる。
562				externalOnly := func() {
563					for _, kv := range []struct{ key, val string }{
564						{"applied_external_url", pl.AppliedExternalURL}, {"notes", pl.Notes},
565					} {
566						if kv.val != "" {
567							add("%s: status %s なのに %s %q があります。%s は status done-external 専用",
568								pn, pl.Status, kv.key, kv.val, kv.key)
569						}
570					}
571				}
572				switch pl.Status {
573				case "pending", "awaiting-human":
574					externalOnly()
575					if pl.SHA != "" {
576						add("%s: status %s なのに sha %q があります。直したのなら status: done にする", pn, pl.Status, pl.SHA)
577					}
578					if pl.Status == "awaiting-human" && pl.Options == "" {
579						add("%s: status awaiting-human には options (選択肢とトレードオフ) が必須", pn)
580					}
581				case "done":
582					externalOnly()
583					if pl.SHA == "" {
584						add("%s: status done には sha (短縮 SHA) が必須。リポジトリ外の成果物への反映で"+
585							"コミットが立たないなら status: done-external にする", pn)
586					}
587				case "done-external":
588					// コミットが無いのだから sha を書けるはずがない。書けているなら
589					// リポジトリ内の修正なので done が正しい。
590					if pl.SHA != "" {
591						add("%s: status done-external なのに sha %q があります。コミットがあるなら status: done にする", pn, pl.SHA)
592					}
593					if pl.AppliedExternalURL == "" && pl.Notes == "" {
594						add("%s: status done-external には applied_external_url (反映先の URL) か "+
595							"notes (反映先と、反映を確認した方法) のどちらかが必須", pn)
596					}
597				default:
598					add("%s: status は pending / awaiting-human / done / done-external のいずれか: %q", pn, pl.Status)
599				}
600				// 調査は任意 (無ければ未調査) だが、書くなら範囲 (scope) が要る。
601				// 範囲の無い調査は「どこまで調べたか」を残さず、未調査と区別できない。
602				if inv := pl.Investigation; inv != nil {
603					if strings.TrimSpace(inv.Scope) == "" {
604						add("%s: investigation.scope がありません (調べた範囲 — 実行したコマンドと目で読んだ対象)。範囲を書かない調査は未調査と区別できない", pn)
605					}
606					for _, kv := range []struct {
607						key  string
608						vals []string
609					}{{"included", inv.Included}, {"excluded", inv.Excluded}} {
610						for i, v := range kv.vals {
611							if strings.TrimSpace(v) == "" {
612								add("%s: investigation.%s[%d] が空です (箇所を書くか要素を消す)", pn, kv.key, i)
613							}
614						}
615					}
616				}
617				for _, d := range pl.DependsOn {
618					if d == pl.ProblemID {
619						add("%s: depends_on が自己参照しています", pn)
620						continue
621					}
622					if !problemIDs[d] {
623						add("%s: depends_on の %q は同じ回の plans にありません", pn, d)
624					}
625				}
626			}
627			// 被覆: 採択は自回の plans か plan_ref で覆われる。覆われない採択は、
628			// 対処しないまま黙って消える。
629			//
630			// 免除するのは「plans がまだ無い最後の回」だけ — fix 前の状態を指す。
631			// 後続の回が追記された時点でその回はもう fix 前ではないので、免除を解く。
632			// 全回で len(run.Plans) > 0 を条件にしていた頃は、plans を書かないまま
633			// 次の回に進んだ過去の回の採択が、検査からも review-triage-fix (最後の回の
634			// findings しか見ない) からも見えなくなり、黙って消えていた。
635			isLastRun := ri == len(doc.Runs)-1
636			if len(run.Plans) > 0 || !isLastRun {
637				covered := map[int]bool{}
638				for _, pl := range run.Plans {
639					for _, id := range pl.FindingIDs {
640						covered[id] = true
641					}
642				}
643				for _, fd := range run.Findings {
644					if fd.Verdict != "adopted" || covered[fd.ID] {
645						continue
646					}
647					if fd.PlanRef != nil {
648						continue // 参照自体の実在は上の finding ループで検査済み
649					}
650					add("%s: findings id %d: 採択が修正計画に載っていません (自回の plans にも plan_ref にも無い)", rn, fd.ID)
651				}
652			}
653			if rec := run.Recurrence; rec != nil {
654				problems = append(problems, recordRecurrenceProblems(f, ri, rec, verdictByID, doc.Runs, plansByRun)...)
