656			for _, cycle := range recordDependsOnCycles(run.Plans) {
657				add("%s: depends_on が循環しています (%s)。順序が定まらない — 同じ原因の 1 問題に束ねるべきものを分けていないかを疑う",
658					rn, strings.Join(cycle, " → "))
659			}
660		}
661		return problems
662	}
