664	// recordRecurrenceProblems は runs[ri].recurrence の形を検査する。ri は 0 始まりの
665	// 添字で、記録上の回番号は ri+1。verdictByID は同じ回の指摘 id → verdict。runs と
666	// plansByRun (回ごとの問題 id の集合) は、根拠の prior が比べた回に実在するかを
667	// 照らすのに使う。
668	//
669	// status ごとに専用のキーの有無を検査する。declined の理由と reframed の捉え直しは
670	// 状態遷移の証拠なので、状態と食い違う記録 (detected なのに捉え直しがある、
671	// declined なのに理由が無い) を黙って通すと、review-triage-fix がどの回を
672	// 未処理と読むかが記録から定まらなくなる。列挙外の status では専用キーの検査を
673	// 重ねない — 1 つの誤字が複数の問題になる (plans の status と同じ扱い)。
674	func recordRecurrenceProblems(f string, ri int, rec *recordRecurrence, verdictByID map[int]string, runs []recordRun, plansByRun []map[string]bool) []string {
675		var problems []string
676		runNo := ri + 1
677		add := func(format string, args ...any) {
678			problems = append(problems, f+": "+fmt.Sprintf("回 %d の recurrence: ", runNo)+fmt.Sprintf(format, args...))
679		}
680		// 回 1 には比べる過去の回が無い (recurrence-detection.md「過去の回が無い記録では判断しない」)。
681		// prior_run の範囲の検査に任せると「直前の回 (0)」という読めない文になるので、先に専用の文で弾く。
682		if runNo == 1 {
683			add("比べる過去の回が無いので書けません (回 1 では検知の判断そのものを行わない)")
684			return problems
685		}
686		if len(rec.Evidence) == 0 {
687			add("evidence がありません (検知の根拠は 1 件以上)")
688		}
689		for ei, ev := range rec.Evidence {
690			en := fmt.Sprintf("evidence[%d]", ei)
691			switch ev.Condition {
692			case "fix-derived", "same-location":
693			default:
694				add("%s: condition は fix-derived / same-location のいずれか: %q", en, ev.Condition)
695			}
696			// 根拠が指す採択。検知は今回の採択と過去を照らすものなので、採択でない指摘や
697			// 存在しない id を根拠にした検知は誤検知か書き誤り。
698			v, ok := verdictByID[ev.FindingID]
699			switch {
700			case !ok:
701				add("%s: finding_id %d は同じ回の findings にありません", en, ev.FindingID)
702			case v != "adopted":
703				add("%s: finding_id %d は採択 (adopted) ではありません (verdict %s)。検知の根拠は採択だけを指す", en, ev.FindingID, v)
704			}
705			// 比べる相手は直前の 1 回 (recurrence-detection.md)。より前の回を指す根拠を通すと、
706			// 俯瞰の第 1 段の図に途中の回を飛ばした辺が描かれる。
707			priorRunOK := ev.PriorRun == runNo-1
708			if !priorRunOK {
709				add("%s: prior_run %d は直前の回 (%d) ではありません (比べる相手は直前の 1 回)", en, ev.PriorRun, runNo-1)
710			}
711			for _, kv := range []struct{ key, val string }{{"prior", ev.Prior}, {"reason", ev.Reason}} {
712				if strings.TrimSpace(kv.val) == "" {
713					add("%s: %s がありません", en, kv.key)
714				}
715			}
716			// fix-derived の prior は比べた回の何かを指す参照で、比べた回の状態で形が決まる。
717			// 形の正本は recurrence-detection.md「直前の回の状態と主の条件」の表 — ここでは
718			// 言い直さず、その表どおりかを照合する。正本に無い形の根拠は書き誤りで、
719			// review-triage-fix が俯瞰で辿る先を失う。same-location の prior は採択を指す
720			// 自由な文字列なので、空でないことだけを見る。prior_run が直前でなければ比べる回が
721			// 定まらないので、この照合は行わない (上で報告済み)。
722			if ev.Condition == "fix-derived" && priorRunOK && strings.TrimSpace(ev.Prior) != "" {
723				priorRun := runs[ev.PriorRun-1]
724				priorReframed := priorRun.Recurrence != nil && priorRun.Recurrence.Status == "reframed"
725				switch {
726				case priorReframed && ev.Prior != "捉え直し":
727					add("%s: 比べた回 %d は捉え直し済みなので prior は 捉え直し と書く: %q (形の正本は recurrence-detection.md の表)", en, ev.PriorRun, ev.Prior)
728				case !priorReframed && !plansByRun[ev.PriorRun-1][ev.Prior]:
729					add("%s: prior %q は回 %d の plans にありません (形の正本は recurrence-detection.md の表)", en, ev.Prior, ev.PriorRun)
730				}
731			}
732		}
733		// 状態と専用キーの排他。
734		noDeclinedReason := func() {
735			if rec.DeclinedReason != "" {
736				add("status %s なのに declined_reason %q があります。declined_reason は status declined 専用", rec.Status, rec.DeclinedReason)
737			}
738		}
739		noReframe := func() {
740			if rec.Reframe != nil {
741				add("status %s なのに reframe があります。reframe は status reframed 専用", rec.Status)
742			}
743		}
744		switch rec.Status {
745		case "detected":
746			noDeclinedReason()
747			noReframe()
748		case "declined":
749			noReframe()
750			if strings.TrimSpace(rec.DeclinedReason) == "" {
751				add("status declined には declined_reason (繰り返しではないと判断した理由) が必須")
752			}
753		case "reframed":
754			noDeclinedReason()
755			rf := rec.Reframe
756			if rf == nil {
757				add("status reframed には reframe (合意した捉え直し) が必須")
758				break
759			}
760			for _, kv := range []struct{ key, val string }{
761				{"pattern", rf.Pattern}, {"axes", rf.Axes}, {"root_cause", rf.RootCause}, {"fix_unit", rf.FixUnit},
762			} {
763				if strings.TrimSpace(kv.val) == "" {
764					add("reframe.%s がありません (捉え直しの 4 項目は必須)", kv.key)
765				}
766			}
767			switch rf.Source {
768			case "human", "skill":
769			default:
770				add("reframe.source は human / skill のいずれか: %q", rf.Source)
771			}
772		default:
773			add("status は detected / declined / reframed のいずれか: %q", rec.Status)
774		}
775		return problems
776	}
