778	// recordDependsOnCycles は plans の depends_on の循環を検出する。自己参照は
779	// 個別に報告するのでここでは扱わない。同じ循環は 1 度だけ返す。
780	func recordDependsOnCycles(plans []recordPlan) [][]string {
781		deps := make(map[string][]string, len(plans))
782		for _, pl := range plans {
783			for _, d := range pl.DependsOn {
784				if d != pl.ProblemID {
785					deps[pl.ProblemID] = append(deps[pl.ProblemID], d)
786				}
787			}
788		}
789		const (
790			visiting = 1
791			done     = 2
792		)
793		state := map[string]int{}
794		var cycles [][]string
795		var stack []string
796		var visit func(id string)
797		visit = func(id string) {
798			state[id] = visiting
799			stack = append(stack, id)

800			for _, d := range deps[id] {
801				switch state[d] {
802				case 0:
803					visit(d)
804				case visiting:
805					// stack の d 以降が循環。
806					for i, s := range stack {
807						if s == d {
808							cycle := append(append([]string{}, stack[i:]...), d)
809							cycles = append(cycles, cycle)
810							break
811						}
812					}
813				}
814			}
815			stack = stack[:len(stack)-1]
816			state[id] = done
817		}
818		for _, pl := range plans {
819			if state[pl.ProblemID] == 0 {
820				visit(pl.ProblemID)
821			}
822		}
823		return cycles
824	}
