1135	// (-record-dir) は「そこを検査せよ」という意思表示なので、不在はエラーにする。
1136	// 未指定 (既定値) のまま不在なのはスキル未導入の正常な状態で、nil を返す。
1137	// 判定を分けないと、置き場を移した時点で検査が黙って無効になる
1138	// (judgment_flow.go の explicit と同じ理由)。
1139	func listReviewTriageFiles(dir string, explicit bool) ([]string, error) {
1140		entries, err := os.ReadDir(dir)
1141		if err != nil {
1142			// ディレクトリが無いのはスキル未導入の正常な状態 (明示指定のときを除く)。
1143			// それ以外 (権限・I/O) のエラーを「記録 0 件」に潰すと、守りが黙って外れる。
1144			// 判定は judgment_flow.go と同じ errors.Is に揃える (ラップされたエラーも
1145			// 正しく分類するため)。
1146			if errors.Is(err, fs.ErrNotExist) {
1147				if explicit {
1148					return nil, errRecordDirMissing
1149				}
1150				return nil, nil
1151			}
1152			return nil, err
1153		}
1154		var files []string
1155		for _, e := range entries {
1156			if e.IsDir() {
1157				continue
1158			}
1159			name := e.Name()
1160			// README.* は記録ではない — README.md は手書きの規範文書で、README.yaml を
1161			// 記録と見なすと生成器が README.md を上書きしてしまう (検査側の除外と対称にする)。
1162			if strings.TrimSuffix(strings.TrimSuffix(name, ".md"), ".yaml") == "README" {
1163				continue
1164			}
1165			if strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".md") {
1166				files = append(files, path.Join(dir, name))
1167			}
1168		}
1169		sort.Strings(files)
1170		return files, nil
1171	}
