1184			}
1185			data, err := os.ReadFile(f)
1186			if err != nil {
1187				return err
1188			}
1189			summary, err := renderReviewTriageSummary(f, data)
1190			if err != nil {
1191				return err
1192			}
1193			mdPath := strings.TrimSuffix(f, ".yaml") + ".md"
1194			if err := os.WriteFile(mdPath, []byte(summary), 0o644); err != nil {
1195				return err
1196			}
1197			fmt.Printf("生成: %s (正本: %s)\n", mdPath, f)
