	// judgmentFlowIDRe はノード ID の形。接頭辞 JN (Judgement Node) に、
	// 判定 (D)・評価 (E)・採択 (A)・保留 (H)・却下 (R) の種別と番号が続く。
	// 接頭辞を付けるのは、JNA1・JND1 のような短い記号が他の文脈 (指摘の番号・
	// 色コード・節番号) でも使われ、読み手が取り違えるため。
	judgmentFlowIDRe = regexp.MustCompile(`\b(JN[ADEHR]\d+)\b`)
	// judgmentFlowTableRowRe は決定表の行 (先頭セルが ID)。パイプ前後の空白の
	// 詰め方には依存しない。
	judgmentFlowTableRowRe = regexp.MustCompile(`^\|\s*(JN[ADEHR]\d+)\s*\|`)
	// judgmentFlowQuoteRe は mermaid のラベル文字列。ID の抽出前に取り除く
	// (ラベル内の "JND1: ..." のような表示用の ID を数えないため)。
	judgmentFlowQuoteRe = regexp.MustCompile(`"[^"]*"`)
	// judgmentFlowColorRe は色コード。ID に接頭辞 JN が付く前は `#JNA12` のような
	// 大文字の短い 16 進が ID の形に一致したため、抽出前に取り除いている。
	// 接頭辞を付けた今は 16 進に J・N が現れないので一致しないが、除去しても
	// 正しい ID は消えないので、防御として残す。
	judgmentFlowColorRe = regexp.MustCompile(`#[0-9A-Fa-f]+`)
	// judgmentFlowSeparatorRe は表の区切り行 (| --- | --- |)。直前の行は見出しで、
	// 先頭セルが ID の形でも本体行として数えない。
	judgmentFlowSeparatorRe = regexp.MustCompile(`^\s*\|(\s*:?-{3,}:?\s*\|)+\s*$`)
)

// judgmentFlowDecorations は ID の出所にしない装飾行の先頭トークン。
var judgmentFlowDecorations = map[string]bool{
	"style": true, "class": true, "classDef": true, "click": true, "linkStyle": true,
}

// judgmentFlowTerminalNodes は決定表から決着ノード (採択 A・保留 H・却下 R) の
// ID 集合を読む。記録の verdict_node がこの集合に含まれるかの照合に使う —
// 形 (正規表現) だけを見ると、判定フローに無いノード ID が素通りし、生成サマリが
