// review_file.go は、上流レビューが別セッションで書き出したレビュー結果ファイル
// (review-request.md の「出力様式」に従う YAML) の様式を検査する (review-file)。
//
// 記録 (record.go) の検査と対になる。記録は 2 つのスキルの間の受け渡しの契約で、
// レビュー結果ファイルは上流レビューとトリアージの間の受け渡しの契約 — どちらも
// 「様式は定まっているが、守られたかを確かめる経路が無い」と、様式外のキーが
// 黙って無視され、無視されたことに誰も気づかない (実測: 修正を記録するキーを
// レビュアが足していて、レビュア自身が修正を適用していたことに手順 1 で初めて
// 気づいた)。
//
// 検査するのは様式だけ。head が現在の HEAD と一致するか、レビューが報告のみで
// 走ったか (作業ツリーが不変か) は git の状態を要するので、スキルの手順 1 が担う。
package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"

	"gopkg.in/yaml.v3"
)

// --- 様式 (正本は skills/review-triage/references/review-request-template.md の出力様式) ---

type reviewFileDoc struct {
	Skill string `yaml:"skill"`
	Model string `yaml:"model"`
	Level string `yaml:"level"`
	RunID string `yaml:"run_id"`
	Scope string `yaml:"scope"`
	Base  string `yaml:"base"`
	Head  string `yaml:"head"`
	Date  string `yaml:"date"`
	// Findings は指摘の列。0 件でも findings: [] と書かせる — キーが無い、または
	// 値が無い (null) 状態を「0 件」と読むと、書き出しの途中で止まったファイルが
	// 「指摘なし」として通る。有無をポインタで持つ。
	Findings *[]reviewFileFinding `yaml:"findings"`
	// Residual は報告しない条件に当たるが残す 1 行メモの列。無ければ空。
	Residual []string `yaml:"residual"`
	// Attrs は上流固有の属性のパススルー (トップレベル)。指摘の attrs と同じ考え方で、
	// 拡張を受ける場所をここ 1 つに決めて、それ以外のトップレベルは閉じる。
	Attrs map[string]any `yaml:"attrs"`
}

type reviewFileFinding struct {
	ID       int            `yaml:"id"`
	File     string         `yaml:"file"`
	Line     int            `yaml:"line"`
	Summary  string         `yaml:"summary"`
	Evidence string         `yaml:"evidence"`
	Attrs    map[string]any `yaml:"attrs"`
}

// reviewFileAllowedKeys は階層ごとに許すキー。未知のキーは報告する — 記録の検査と
// 同じ理由 (旧いキー名や様式外のキーが「エラーなしで無視」に化ける型を避ける) に
// 加えて、レビュアが足したキーは「様式に無い作業をした」ことの痕跡でもある
// (修正を記録するキーは、レビュアが修正を適用した印)。attrs だけは任意のキーを許す。
var reviewFileAllowedKeys = map[string]map[string]bool{
	"トップレベル": {"skill": true, "model": true, "level": true, "run_id": true, "scope": true,
		"base": true, "head": true, "date": true, "findings": true, "residual": true, "attrs": true},
	"指摘": {"id": true, "file": true, "line": true, "summary": true, "evidence": true, "attrs": true},
}

// reviewFileProblems は 1 つのレビュー結果ファイルの様式を検査する。
// 検査は (1) YAML として読めるか、(2) 行内コメント、(3) 未知のキー、(4) 必須キー・
// 列挙値・id の連番。記録の検査 (recordProblemsInYAML) と同じ順で、同じ種類の
// 問題を同じ文言の型で報告する。
func reviewFileProblems(f string, data []byte) []string {
	var root yaml.Node
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&root); err != nil {
		if errors.Is(err, io.EOF) {
			return []string{fmt.Sprintf("%s: レビュー結果が空です (様式のキーが 1 つもありません)", f)}
		}
		return []string{fmt.Sprintf("%s: YAML を解析できません: %v", f, err)}
	}
	var extra yaml.Node
	if err := dec.Decode(&extra); err == nil {
		return []string{fmt.Sprintf(
			"%s: --- 区切りの 2 つ目のドキュメントがあります — レビュー結果は単一ドキュメントで、2 つ目以降は読まれず消える", f)}
	} else if !errors.Is(err, io.EOF) {
		return []string{fmt.Sprintf("%s: 2 つ目のドキュメントの解析に失敗しました: %v", f, err)}
	}
	if len(root.Content) == 0 ||
		(root.Content[0].Kind == yaml.ScalarNode && root.Content[0].Tag == "!!null") {
		return []string{fmt.Sprintf("%s: レビュー結果が空です (様式のキーが 1 つもありません)", f)}
	}
	if root.Content[0].Kind != yaml.MappingNode {
		return []string{fmt.Sprintf("%s: トップレベルが写像ではありません (様式は skill: … から始まる写像)", f)}
	}
	problems := recordLineCommentProblems(f, &root)
	problems = append(problems, reviewFileUnknownKeyProblems(f, root.Content[0])...)
	var doc reviewFileDoc
	if err := root.Decode(&doc); err != nil {
		problems = append(problems, fmt.Sprintf("%s: 様式に合いません: %v", f, err))
		return problems
	}
	return append(problems, reviewFileSemanticProblems(f, &doc)...)
}

// reviewFileUnknownKeyProblems は許可キー集合との突き合わせで未知のキーを列挙する。
// attrs の中は見ない (パススルー)。問題が見つかっても走査を続ける。
func reviewFileUnknownKeyProblems(f string, n *yaml.Node) []string {
	var problems []string
	var walkMap func(n *yaml.Node, kind string)
	walkMap = func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.MappingNode {
			return
		}
		allowed := reviewFileAllowedKeys[kind]
		for i := 0; i+1 < len(n.Content); i += 2 {
			k, v := n.Content[i], n.Content[i+1]
			if !allowed[k.Value] {
				problems = append(problems, fmt.Sprintf(
					"%s:%d: %sに未知のキー %q。様式に無いキーは attrs へ入れる (修正を記録するキーなら、レビューが報告のみで走っていない印)",
					f, k.Line, kind, k.Value))
				continue
			}
			if k.Value == "findings" && v.Kind == yaml.SequenceNode {
				for _, item := range v.Content {
					walkMap(item, "指摘")
				}
			}
		}
	}
	walkMap(n, "トップレベル")
	return problems
}

// reviewFileSemanticProblems は必須キー・列挙値・id の連番を検査する。
func reviewFileSemanticProblems(f string, doc *reviewFileDoc) []string {
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, f+": "+fmt.Sprintf(format, args...))
	}
	for _, kv := range []struct{ key, val string }{
		{"skill", doc.Skill}, {"model", doc.Model}, {"base", doc.Base}, {"head", doc.Head},
	} {
		if strings.TrimSpace(kv.val) == "" {
			add("%s がありません", kv.key)
		}
	}
	if !recordDateRe.MatchString(doc.Date) {
		add("date が YYYY-MM-DD ではありません: %q", doc.Date)
	}
	if doc.Scope != "incremental" && doc.Scope != "full" {
		add("scope は incremental / full のいずれか: %q", doc.Scope)
	}
	if doc.Findings == nil {
		add("findings がありません (指摘が 0 件でも findings: [] と書く。値の無い findings: は「無い」と同じに読まれる)")
	} else {
		for i, fd := range *doc.Findings {
			fn := fmt.Sprintf("findings[%d] (id %d)", i, fd.ID)
			// id は 1 からの連番。飛びや重複があると、トリアージ側が記録に写した id と
			// レビュアの id が食い違い、保留の提示で「指摘 3」がどれを指すか定まらない。
			if fd.ID != i+1 {
				add("%s: id は 1 からの連番にする (この位置は %d)", fn, i+1)
			}
			for _, kv := range []struct{ key, val string }{
				{"file", fd.File}, {"summary", fd.Summary}, {"evidence", fd.Evidence},
			} {
				if strings.TrimSpace(kv.val) == "" {
					add("%s: %s がありません", fn, kv.key)
				}
			}
			if fd.Line < 0 {
				add("%s: line は正の整数にする (不明なら省略): %d", fn, fd.Line)
			}
		}
	}
	for i, r := range doc.Residual {
		if strings.TrimSpace(r) == "" {
			add("residual[%d] が空です (1 行の要旨を書くか要素を消す)", i)
		}
	}
	return problems
}

