package main

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// validReviewFileYAML は review-request-template.md の出力様式に沿ったレビュー結果の
// フィクスチャ。トップレベルと指摘の両方に attrs (パススルー) を持つ。
const validReviewFileYAML = `skill: code-review
model: opus-5
level: high
run_id: ""
scope: incremental
base: main
head: "abc1234"
date: "2026-09-04"
attrs:
  pr: 26
  branch: feat/foo
findings:
  - id: 1
    file: docs/foo.md
    line: 12
    summary: "数の食い違い"
    evidence: "docs/foo.md:12 の逐語引用 — 「3 件」だが数えると 4 件"
    attrs:
      severity: P2
      confidence: high
  - id: 2
    file: tools/bar.go
    summary: "エラーを握りつぶしている"
    evidence: "tools/bar.go:40-42 の逐語引用"
residual:
  - "命名の統一 (放置して壊れるものが無い)"
`

func TestReviewFileValidPasses(t *testing.T) {
	if got := reviewFileProblems("r.yaml", []byte(validReviewFileYAML)); len(got) != 0 {
		t.Fatalf("有効なレビュー結果に問題が報告された: %v", got)
	}
}

// 様式に無いキーは、トップレベルでも指摘でも報告する。実測で足されたキー
// (head_reviewed / pr / branch / outcome / fixed_in) を使い、attrs へ入れれば通ることも
// 同じテストで固定する (トップレベルの attrs が受け皿として機能していること)。
func TestReviewFileReportsUnknownKeys(t *testing.T) {
	cases := []struct {
		name   string
		mutate func(string) string
		want   string
	}{
		{"トップレベルの head_reviewed", func(s string) string { return "head_reviewed: abc1234\n" + s }, `未知のキー "head_reviewed"`},
		{"トップレベルの pr", func(s string) string { return "pr: 26\n" + s }, `未知のキー "pr"`},
		{"指摘の outcome", func(s string) string {
			return strings.Replace(s, "    evidence: \"tools/bar.go:40-42 の逐語引用\"\n",
				"    evidence: \"tools/bar.go:40-42 の逐語引用\"\n    outcome: fixed\n", 1)
		}, `未知のキー "outcome"`},
		{"指摘の fixed_in", func(s string) string {
			return strings.Replace(s, "    evidence: \"tools/bar.go:40-42 の逐語引用\"\n",
				"    evidence: \"tools/bar.go:40-42 の逐語引用\"\n    fixed_in: def5678\n", 1)
		}, `未知のキー "fixed_in"`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := reviewFileProblems("r.yaml", []byte(tc.mutate(validReviewFileYAML)))
			if len(got) != 1 || !strings.Contains(got[0], tc.want) {
				t.Fatalf("期待した報告 (%s) と違う: %v", tc.want, got)
			}
		})
	}
}

// 必須キー・列挙値・連番の検査。1 つの誤りが 1 つの問題として報告されること。
func TestReviewFileSemanticProblems(t *testing.T) {
	cases := []struct {
		name string
		yaml string
		want string
	}{
		{"scope が列挙外", strings.Replace(validReviewFileYAML, "scope: incremental", "scope: pr", 1), "scope は incremental / full"},
		{"date の形", strings.Replace(validReviewFileYAML, `date: "2026-09-04"`, `date: "2026/09/04"`, 1), "date が YYYY-MM-DD ではありません"},
		{"model が空", strings.Replace(validReviewFileYAML, "model: opus-5", `model: ""`, 1), "model がありません"},
		{"base が無い", strings.Replace(validReviewFileYAML, "base: main\n", "", 1), "base がありません"},
		{"head が無い", strings.Replace(validReviewFileYAML, `head: "abc1234"`+"\n", "", 1), "head がありません"},
		{"evidence が空", strings.Replace(validReviewFileYAML, `evidence: "tools/bar.go:40-42 の逐語引用"`, `evidence: ""`, 1), "findings[1] (id 2): evidence がありません"},
		{"id が連番でない", strings.Replace(validReviewFileYAML, "  - id: 2\n", "  - id: 3\n", 1), "findings[1] (id 3): id は 1 からの連番にする (この位置は 2)"},
		{"id が重複", strings.Replace(validReviewFileYAML, "  - id: 2\n", "  - id: 1\n", 1), "findings[1] (id 1): id は 1 からの連番にする (この位置は 2)"},
		{"residual が空文字", strings.Replace(validReviewFileYAML, `  - "命名の統一 (放置して壊れるものが無い)"`, `  - ""`, 1), "residual[0] が空です"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := reviewFileProblems("r.yaml", []byte(tc.yaml))
			if len(got) != 1 || !strings.Contains(got[0], tc.want) {
				t.Fatalf("期待した報告 (%s) と違う: %v", tc.want, got)
			}
		})
	}
}

// findings は 0 件でも findings: [] と書く。キーが無い・値が無い (null) を「0 件」と
// 読むと、書き出しの途中で止まったファイルが「指摘なし」として通る。
// 空の findings: [] はそのまま通る (指摘 0 件の正しい形)。
func TestReviewFileRequiresFindingsKey(t *testing.T) {
	const head = "skill: code-review\nmodel: opus-5\nscope: full\nbase: main\nhead: abc1234\ndate: \"2026-09-04\"\n"
	cases := []struct {
		name string
		yaml string
		want bool
	}{
		{"findings が無い", head, true},
		{"findings が null", head + "findings:\n", true},
		{"findings が空の列", head + "findings: []\n", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := reviewFileProblems("r.yaml", []byte(tc.yaml))
			if tc.want {
				if len(got) != 1 || !strings.Contains(got[0], "findings がありません") {
					t.Fatalf("findings の欠落が報告されていない: %v", got)
				}
				return
			}
			if len(got) != 0 {
				t.Fatalf("findings: [] に問題が報告された: %v", got)
			}
		})
	}
}

// 行内コメントは記録と同じ理由 (値が黙って切り詰められる) で報告する。
// 様式の雛形にはコメント付きの例が載っているので、雛形をそのまま写した結果が
// ここで捕まる — 雛形の側でコメントを付けない形にしておく根拠でもある。
func TestReviewFileReportsLineComment(t *testing.T) {
	y := strings.Replace(validReviewFileYAML, "scope: incremental", "scope: incremental # 範囲の規則のとおり", 1)
	got := reviewFileProblems("r.yaml", []byte(y))
	if len(got) != 1 || !strings.Contains(got[0], "行内コメント") {
		t.Fatalf("行内コメントが報告されていない: %v", got)
	}
}

// 空・null・2 つ目のドキュメント・写像でないトップレベルは、様式の検査に入る前に
// それぞれ専用の文言で止める (記録の検査と同じ順)。
func TestReviewFileRejectsUnreadableShapes(t *testing.T) {
	cases := []struct {
		name string
		yaml string
		want string
	}{
		{"空", "", "レビュー結果が空です"},
		{"コメントのみ", "# nothing\n", "レビュー結果が空です"},
		{"null", "~\n", "レビュー結果が空です"},
		{"列がトップレベル", "- skill: code-review\n", "トップレベルが写像ではありません"},
		{"2 つ目のドキュメント", validReviewFileYAML + "---\nskill: x\n", "2 つ目のドキュメント"},
		{"壊れた YAML", "skill: [\n", "YAML を解析できません"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := reviewFileProblems("r.yaml", []byte(tc.yaml))
			if len(got) != 1 || !strings.Contains(got[0], tc.want) {
				t.Fatalf("期待した報告 (%s) と違う: %v", tc.want, got)
			}
		})
	}
}

// -review-file の経路も、他の経路と同じパスの規則に従う (相対には基準が要る、
// 空は弾く、不在は報告して非 0)。規則は resolveInputs の 1 か所にあり、この経路の
// ために書き直していないことを固定する。
func TestRunReviewFileSharesPathRules(t *testing.T) {
	repo := realTempDir(t)
	recs := filepath.Join(repo, "docs", "rt")
	if err := os.MkdirAll(recs, 0o755); err != nil {
		t.Fatal(err)
	}
	rf := filepath.Join(repo, "tmp", "review-1-code-review-opus-5.yaml")
	if err := os.MkdirAll(filepath.Dir(rf), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(rf, []byte(validReviewFileYAML), 0o644); err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name    string
		args    []string
		wantErr error
	}{
		{"絶対パスで通る", []string{"-record-dir", recs, "-review-file", rf}, nil},
		{"相対パスと -current-dir で通る", []string{"-current-dir", repo, "-record-dir", "docs/rt", "-review-file", "tmp/review-1-code-review-opus-5.yaml"}, nil},
		{"相対パスに基準が無い", []string{"-record-dir", recs, "-review-file", "tmp/review-1-code-review-opus-5.yaml"}, nil},
		{"空のパス", []string{"-record-dir", recs, "-review-file", "  "}, errEmptyPath},
		{"不在", []string{"-record-dir", recs, "-review-file", filepath.Join(repo, "tmp", "no-such.yaml")}, errPathMissing},
		{"-install-wrapper と併用", []string{"-record-dir", recs, "-review-file", rf, "-install-wrapper", filepath.Join(repo, "bin", "w")}, errFlagUnusedWithReviewFile},
		{"-write-summary と併用", []string{"-record-dir", recs, "-review-file", rf, "-write-summary"}, errFlagUnusedWithReviewFile},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			withRunGlobals(t)
			err := run(tc.args)
			switch {
			case tc.name == "相対パスに基準が無い":
				if err == nil || !strings.Contains(err.Error(), "-review-file") {
					t.Fatalf("相対の -review-file に基準を要求していない: %v", err)
				}
			case tc.wantErr == nil:
				if err != nil {
					t.Fatalf("通るべき呼び出しがエラーになった: %v", err)
				}
			default:
				if !errors.Is(err, tc.wantErr) {
					t.Fatalf("期待したエラー (%v) と違う: %v", tc.wantErr, err)
				}
			}
		})
	}
}

// -review-file は様式の問題を非 0 で報告する。記録の検査には進まない (記録の置き場が
// 空でも、レビュー結果の問題だけが報告される)。
func TestRunReviewFileReportsProblems(t *testing.T) {
	repo := realTempDir(t)
	recs := filepath.Join(repo, "docs", "rt")
	if err := os.MkdirAll(recs, 0o755); err != nil {
		t.Fatal(err)
	}
	rf := filepath.Join(repo, "review.yaml")
	bad := strings.Replace(validReviewFileYAML, "scope: incremental", "scope: pr", 1)
	if err := os.WriteFile(rf, []byte(bad), 0o644); err != nil {
		t.Fatal(err)
	}
	withRunGlobals(t)
	if err := run([]string{"-record-dir", recs, "-review-file", rf}); err == nil {
		t.Fatal("様式外の scope を持つレビュー結果が通った")
	}
}

