	// なるので、書かれたとおりに読まれることを保証するために !!str を要求する。
	// date は形 (YYYY-MM-DD) を意味検査が見るので、ここでは型を見ない (引用符の無い
	// 日付は !!timestamp に解決され、文字列として正しく読める)。
	requireStr := func(v *yaml.Node, key string) {
		if v.Kind == yaml.ScalarNode && v.Tag != "!!str" && !isNull(v) {
			add(v.Line, "%s は文字列で書く (引用符の無い %s は %s として読まれ、書かれたとおりに残らない)", key, v.Value, v.Tag)
		}
	}
	// 整数の欄。小数は int に切り詰められ、文字列は decode で失敗するが文言が読めない。
	requireInt := func(v *yaml.Node, key string, min int) {
		if v.Kind != yaml.ScalarNode || isNull(v) {
			return
		}
		if v.Tag != "!!int" {
			add(v.Line, "%s は整数で書く: %q (%s)", key, v.Value, v.Tag)
			return
		}
		if i, err := strconv.Atoi(v.Value); err == nil && i < min {
			add(v.Line, "%s は %d 以上の整数にする: %d", key, min, i)
		}
	}
	strKeys := map[string]bool{"skill": true, "model": true, "level": true, "run_id": true,
		"scope": true, "base": true, "head": true, "file": true, "summary": true, "evidence": true}

	var walkMap func(n *yaml.Node, kind string)
	walkMap = func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.MappingNode {
			return
		}
		allowed := reviewFileAllowedKeys[kind]
		for i := 0; i+1 < len(n.Content); i += 2 {
			k, v := n.Content[i], n.Content[i+1]
			if !allowed[k.Value] {
				add(k.Line, "%sに未知のキー %q。様式に無いキーは attrs へ入れる (修正を記録するキーなら、レビューが報告のみで走っていない印)", kind, k.Value)
				continue
			}
			switch {
			case strKeys[k.Value]:
				requireStr(v, k.Value)
			case k.Value == "id":
				requireInt(v, "id", 1)
			case k.Value == "line":
				// 不明なら省略する欄。0 は省略と区別できず、記録から行番号が黙って消える。
				requireInt(v, "line", 1)
			case k.Value == "findings" && v.Kind == yaml.SequenceNode:
				for j, item := range v.Content {
					if isNull(item) {
						add(item.Line, "findings[%d] に中身がありません (書きかけの要素は列から落ちて「無い」と同じに読まれる)", j)
						continue
					}
					walkMap(item, "指摘")
				}
			case k.Value == "residual" && v.Kind == yaml.SequenceNode:
				for j, item := range v.Content {
					if isNull(item) {
						add(item.Line, "residual[%d] に中身がありません (1 行の要旨を書くか要素を消す)", j)
						continue
					}
					requireStr(item, fmt.Sprintf("residual[%d]", j))
				}
			}
		}
	}
	walkMap(n, "トップレベル")
	return problems
}

