145	// 決定表のパイプ前後の空白の詰め方が違っても ID は収集される。
146	func TestJudgmentFlowTableSpacingVariants(t *testing.T) {
147		content := strings.Replace(judgmentFlowFixture,
148			"| D1 | 判定 | 分類に当たるか | category |\n",
149			"|D1| 判定 | 分類に当たるか | category |\n", 1)
150		if problems := judgmentFlowProblems([]string{judgmentFlowPath}, judgmentFlowRead(content), ""); len(problems) != 0 {
151			t.Fatalf("空白を詰めた表の行の ID が収集されない: %v", problems)
152		}
153	}
154	
155	// 見出しの先頭セルが ID の形でも、直後が区切り行なら本体行として数えない
156	// (偽の重複報告を出さない)。
157	func TestJudgmentFlowHeaderRowNotCounted(t *testing.T) {
158		content := strings.Replace(judgmentFlowFixture,
159			"| ID | 種類 | 条件・内容 | 記録に書くもの |\n",
160			"| D1 | 種類 | 条件・内容 | 記録に書くもの |\n", 1)
161		problems := judgmentFlowProblems(nil, judgmentFlowRead(content), "")
162		for _, p := range problems {
163			if strings.Contains(p, "重複") {
164				t.Fatalf("見出し行の D1 が本体行として数えられ、偽の重複が報告された: %v", p)
165			}
166		}
167	}
168	
169	func TestJudgmentFlowMissingDiagram(t *testing.T) {
170		content := "# 判定フロー\n\n| ID | 種類 |\n| --- | --- |\n| D1 | 判定 |\n"
171		problems := judgmentFlowProblems([]string{judgmentFlowPath}, judgmentFlowRead(content), "")
172		if len(problems) == 0 {
173			t.Fatalf("mermaid の図が無いのに問題が出ない")
174		}
175	}
176	
177	// readFile の失敗は問題として報告される (黙って緑にしない)。
178	func TestJudgmentFlowReadError(t *testing.T) {
179		read := func(_ string) ([]byte, error) { return nil, os.ErrPermission }
180		problems := judgmentFlowProblems([]string{judgmentFlowPath}, read, "")
181		found := false
182		for _, p := range problems {
183			if strings.Contains(p, "読み込みに失敗") {
184				found = true
185			}
186		}
187		if !found {
188			t.Fatalf("readFile の失敗が報告されない。出た問題: %v", problems)
189		}
190	}
191	
192	// mermaid はあるが決定表の行が 1 つも無い場合は報告される。
193	func TestJudgmentFlowMissingTable(t *testing.T) {
194		content := "# 判定フロー\n\n```mermaid\nflowchart TD\n  D1{\"D1: x\"}\n```\n"
195		problems := judgmentFlowProblems([]string{judgmentFlowPath}, judgmentFlowRead(content), "")
196		found := false
197		for _, p := range problems {
198			if strings.Contains(p, "決定表") {
199				found = true
200			}
201		}
202		if !found {
203			t.Fatalf("決定表の不在が報告されない。出た問題: %v", problems)
204		}
205	}
