207	// git 追跡に依らず、ファイルが読めれば検査する — 追跡前の判定フローが
208	// 素通りする「0 件マッチで黙って緑」の型 (B1 と同じ) を塞ぐ。
209	func TestJudgmentFlowChecksUntrackedFile(t *testing.T) {
210		problems := judgmentFlowProblems(nil, judgmentFlowRead("# 図も表も無い\n"), "")
211		if len(problems) == 0 {
