228	// 報告にはどちらの指定を直せばよいか (origin) を載せる — 解決の経路が 2 つあるため。
229	func TestJudgmentFlowAbsentFileReportedWhenOriginGiven(t *testing.T) {
230		read := func(_ string) ([]byte, error) { return nil, fs.ErrNotExist }
231		for _, origin := range []string{"-judgment-flow", "CLAUDE_PLUGIN_ROOT"} {
