package main

import (
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// judgmentFlowTables は決定表と遷移表の最小のフィクスチャ。判定 (D)・評価 (E)・
// 採択 (A)・保留 (H)・却下 (R) を 1 つずつ以上持ち、種類ごとの規則をすべて満たす。
const judgmentFlowTables = "| ID | 種類 | 表示名 | 条件・内容 | 記録に書くもの |\n" +
	"| --- | --- | --- | --- | --- |\n" +
	"| D1 | 判定 | 分類に当たるか | 分類に当たるか | category |\n" +
	"| E1 | 評価 | 根拠の検証 | 段 A | premise_check |\n" +
	"| D2 | 判定 | 人間が保留を解いたか | 人間が判断した後 | — |\n" +
	"| A2 | 決着 | 採択 | 採択 | verdict |\n" +
	"| H1 | 決着 | 保留 (種類不明) | 保留 | verdict |\n" +
	"| R1 | 決着 | 却下 (根拠誤り) | 却下 | verdict |\n" +
	"\n## 遷移表\n\n" +
	"| 始点 | 条件 | 遷移先 |\n" +
	"| --- | --- | --- |\n" +
	"| D1 | 当たらない | H1 |\n" +
	"| D1 | 当たる | E1 |\n" +
	"| E1 |  | D2 |\n" +
	"| D2 | 採択に変えた | A2 |\n" +
	"| D2 | 却下に変えた | R1 |\n" +
	"| H1 | 人間が判断 | D2 |\n"

// judgmentFlowDiagram は上の表から生成される図。フィクスチャの鮮度を固定する —
// 生成器の出力の形 (ノードの形・辺の書き方・色の並び) が変わればここも変わる。
const judgmentFlowDiagram = "flowchart TD\n" +
	"  D1{\"D1: 分類に当たるか\"}\n" +
	"  E1[\"E1: 根拠の検証\"]\n" +
	"  D2{\"D2: 人間が保留を解いたか\"}\n" +
	"  A2[\"A2: 採択\"]\n" +
	"  H1[\"H1: 保留 (種類不明)\"]\n" +
	"  R1[\"R1: 却下 (根拠誤り)\"]\n" +
	"\n" +
	"  D1 -- 当たらない --> H1\n" +
	"  D1 -- 当たる --> E1\n" +
	"  E1 --> D2\n" +
	"  D2 -- 採択に変えた --> A2\n" +
	"  D2 -- 却下に変えた --> R1\n" +
	"  H1 -- 人間が判断 --> D2\n" +
	"\n" +
	"  style A2 fill:#16a34a2e,stroke:#16803c,stroke-width:2px\n" +
	"  style H1 fill:#f59e0b2e,stroke:#b45309\n" +
	"  style R1 fill:#dc26262e,stroke:#b91c1c\n" +
	"  style E1 fill:#6366f12e,stroke:#4f46e5"

// judgmentFlowFixture は図・決定表・遷移表がそろい、図が表と一致する最小のフィクスチャ。
const judgmentFlowFixture = "# 判定フロー\n\n## 図\n\n```mermaid\n" + judgmentFlowDiagram + "\n```\n\n## 決定表\n\n" + judgmentFlowTables

func judgmentFlowRead(content string) func(string) ([]byte, error) {
	return func(_ string) ([]byte, error) { return []byte(content), nil }
}

func judgmentFlowCheck(content string) []string {
	return judgmentFlowProblems([]string{judgmentFlowPath}, judgmentFlowRead(content), "")
}

func judgmentFlowExpectOne(t *testing.T, content, want string) {
	t.Helper()
	problems := judgmentFlowCheck(content)
	if len(problems) != 1 || !strings.Contains(problems[0], want) {
		t.Fatalf("期待した報告 (%s) と違う: %v", want, problems)
	}
}

func TestJudgmentFlowConsistentPasses(t *testing.T) {
	if problems := judgmentFlowCheck(judgmentFlowFixture); len(problems) != 0 {
		t.Fatalf("一致しているのに問題が出た: %v", problems)
	}
}

// 図は生成物。表と食い違えば報告する (手で図を編集した・表を変えて生成し直していない)。
func TestJudgmentFlowStaleDiagram(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "  D1 -- 当たる --> E1\n", "  D1 -- 当たる --> E1\n  H1 --> H1\n", 1)
	judgmentFlowExpectOne(t, content, "図が正本 (決定表・遷移表) と食い違っています")
}

// 保留ノードは人間の判断を待つ状態なので、判断が返ったときの遷移先が要る。
// 以前は手描きの図で H7 の遷移が書き忘れられたまま残った (実測)。
func TestJudgmentFlowHeldNodeNeedsTransition(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "| H1 | 人間が判断 | D2 |\n", "", 1)
	judgmentFlowExpectOne(t, content, "保留ノード H1 からの遷移がありません")
}

// 保留からの遷移先は判定 (D)。決着や評価へ直接進む遷移は規則違反。
func TestJudgmentFlowHeldNodeTransitionsToDecision(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "| H1 | 人間が判断 | D2 |\n", "| H1 | 人間が判断 | A2 |\n", 1)
	judgmentFlowExpectOne(t, content, "保留ノード H1 からの遷移先 A2 が判定ノードではありません")
}

// 採択・却下は決着なので遷移しない。遷移表に始点として現れたら報告する —
// 「報告が出ない」ことではなく「遷移が無い」という規則を肯定の形で検査する。
func TestJudgmentFlowSettledNodesDoNotTransition(t *testing.T) {
	for _, id := range []string{"A2", "R1"} {
		t.Run(id, func(t *testing.T) {
			content := judgmentFlowFixture + "| " + id + " | 戻る | D1 |\n"
			judgmentFlowExpectOne(t, content, "決着ノード "+id+" から D1 への遷移があります")
		})
	}
}

// 判定は 2 つ以上に分かれる。1 本しか無い判定は分岐ではない。
func TestJudgmentFlowDecisionNeedsBranches(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "| D2 | 却下に変えた | R1 |\n", "", 1)
	problems := judgmentFlowCheck(content)
	found := false
	for _, p := range problems {
		if strings.Contains(p, "判定ノード D2 の遷移が 1 本です") {
			found = true
		}
	}
	if !found {
		t.Fatalf("1 本しか無い判定が報告されない: %v", problems)
	}
}

// 評価は次の 1 つに進む。0 本 (行き止まり) も 2 本 (分岐) も報告する。
func TestJudgmentFlowEvaluationHasSingleTransition(t *testing.T) {
	cases := []struct{ name, content, want string }{
		{"0 本", strings.Replace(judgmentFlowFixture, "| E1 |  | D2 |\n", "", 1), "評価ノード E1 の遷移が 0 本です"},
		{"2 本", judgmentFlowFixture + "| E1 | 別の道 | A2 |\n", "評価ノード E1 の遷移が 2 本です"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			problems := judgmentFlowCheck(tc.content)
			found := false
			for _, p := range problems {
				if strings.Contains(p, tc.want) {
					found = true
				}
			}
			if !found {
				t.Fatalf("期待した報告 (%s) が無い: %v", tc.want, problems)
			}
		})
	}
}

// 決定表にあるが、最初のノードから辿り着けないノードは報告する (判定の途中で使われない)。
func TestJudgmentFlowUnreachableNode(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "| R1 | 決着 | 却下 (根拠誤り) | 却下 | verdict |\n",
		"| R1 | 決着 | 却下 (根拠誤り) | 却下 | verdict |\n| H2 | 決着 | 保留 (被害者不定) | 保留 | verdict |\n", 1)
	content += "| H2 | 人間が判断 | D2 |\n"
	judgmentFlowExpectOne(t, content, "H2 に最初のノード D1 から到達できません")
}

// 遷移表の始点・遷移先は決定表に実在すること。
func TestJudgmentFlowTransitionEndpointsMustExist(t *testing.T) {
	cases := []struct{ name, row, want string }{
		{"遷移先が無い", "| D1 | 別の道 | D9 |\n", `遷移先 "D9" は決定表にありません`},
		{"始点が無い", "| H9 | 人間が判断 | D2 |\n", `始点 "H9" は決定表にありません`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			judgmentFlowExpectOne(t, judgmentFlowFixture+tc.row, tc.want)
		})
	}
}

// 同じ遷移の行が 2 つあれば報告する。
func TestJudgmentFlowDuplicateTransition(t *testing.T) {
	judgmentFlowExpectOne(t, judgmentFlowFixture+"| D1 | 当たる | E1 |\n", "D1 から E1 への遷移 (当たる) が重複しています")
}

// 決定表の行の形: ID の形、重複、種類と ID の先頭文字の整合、表示名の有無。
func TestJudgmentFlowDecisionTableRowProblems(t *testing.T) {
	cases := []struct{ name, content, want string }{
		{"ID の形", strings.Replace(judgmentFlowFixture, "| R1 | 決着 | 却下 (根拠誤り) |", "| X1 | 決着 | 却下 (根拠誤り) |", 1), `ID "X1" はノード ID の形`},
		{"重複", strings.Replace(judgmentFlowFixture, "| A2 | 決着 | 採択 | 採択 | verdict |\n", "| A2 | 決着 | 採択 | 採択 | verdict |\n| A2 | 決着 | 採択 | 重複 | verdict |\n", 1), "A2 の行が決定表で重複しています"},
		{"種類の不整合", strings.Replace(judgmentFlowFixture, "| A2 | 決着 | 採択 |", "| A2 | 判定 | 採択 |", 1), `A2 の種類が "判定" です (ID の先頭文字からは 決着)`},
		{"表示名が無い", strings.Replace(judgmentFlowFixture, "| A2 | 決着 | 採択 | 採択 | verdict |", "| A2 | 決着 |  | 採択 | verdict |", 1), "A2 の表示名がありません"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			problems := judgmentFlowCheck(tc.content)
			found := false
			for _, p := range problems {
				if strings.Contains(p, tc.want) {
					found = true
				}
			}
			if !found {
				t.Fatalf("期待した報告 (%s) が無い: %v", tc.want, problems)
			}
		})
	}
}

// 表に問題がある間は図の鮮度を比べない (直せば両方直る)。ID の形の誤りを 1 つ入れた
// とき、鮮度の報告が重ならないことで固定する。
func TestJudgmentFlowSkipsFreshnessWhileTablesBroken(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "| R1 | 決着 | 却下 (根拠誤り) |", "| X1 | 決着 | 却下 (根拠誤り) |", 1)
	for _, p := range judgmentFlowCheck(content) {
		if strings.Contains(p, "食い違っています") {
			t.Fatalf("表が壊れているのに鮮度の報告が重なった: %v", p)
		}
	}
}

// 決定表のパイプ前後の空白の詰め方が違っても読める。
func TestJudgmentFlowTableSpacingVariants(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture,
		"| D1 | 判定 | 分類に当たるか | 分類に当たるか | category |\n",
		"|D1|判定|分類に当たるか| 分類に当たるか |category|\n", 1)
	if problems := judgmentFlowCheck(content); len(problems) != 0 {
		t.Fatalf("空白を詰めた表の行が読めない: %v", problems)
	}
}

// 見出しの先頭セルが ID でも 始点 でもない表 (他の説明の表) は読まない。
func TestJudgmentFlowIgnoresOtherTables(t *testing.T) {
	content := strings.Replace(judgmentFlowFixture, "## 決定表\n\n",
		"## 別の表\n\n| 項目 | 内容 |\n| --- | --- |\n| D9 | 説明 |\n\n## 決定表\n\n", 1)
	if problems := judgmentFlowCheck(content); len(problems) != 0 {
		t.Fatalf("別の表の行が決定表として読まれた: %v", problems)
	}
}

func TestJudgmentFlowMissingDiagram(t *testing.T) {
	content := "# 判定フロー\n\n## 決定表\n\n" + judgmentFlowTables
	judgmentFlowExpectOne(t, content, "mermaid の図が見つかりません")
}

// 決定表・遷移表の不在はそれぞれ報告する。
func TestJudgmentFlowMissingTables(t *testing.T) {
	content := "# 判定フロー\n\n```mermaid\n" + judgmentFlowDiagram + "\n```\n"
	problems := judgmentFlowCheck(content)
	joined := strings.Join(problems, "\n")
	for _, want := range []string{"決定表", "遷移表"} {
		if !strings.Contains(joined, want) {
			t.Fatalf("%s の不在が報告されない: %v", want, problems)
		}
	}
}

// readFile の失敗は問題として報告される (黙って緑にしない)。
func TestJudgmentFlowReadError(t *testing.T) {
	read := func(_ string) ([]byte, error) { return nil, os.ErrPermission }
	problems := judgmentFlowProblems([]string{judgmentFlowPath}, read, "")
	if len(problems) != 1 || !strings.Contains(problems[0], "読み込みに失敗") {
		t.Fatalf("readFile の失敗が報告されない。出た問題: %v", problems)
	}
}

// git 追跡に依らず、ファイルが読めれば検査する — 追跡前の判定フローが
// 素通りする「0 件マッチで黙って緑」の型を塞ぐ。
func TestJudgmentFlowChecksUntrackedFile(t *testing.T) {
	if problems := judgmentFlowCheck("# 図も表も無い\n"); len(problems) == 0 {
		t.Fatalf("追跡外でも読める判定フローが検査されない")
	}
}

// ファイルがそもそも無いリポジトリ (スキル未導入) では検査は黙って通る。
// 在り処の指定が無い (origin が空) ときだけの扱いであることは、次のテストが対にする。
func TestJudgmentFlowAbsentFileSkipped(t *testing.T) {
	read := func(_ string) ([]byte, error) { return nil, fs.ErrNotExist }
	if problems := judgmentFlowProblems(nil, read, ""); len(problems) != 0 {
		t.Fatalf("対象ファイルが無いのに問題が出た: %v", problems)
	}
}

// 在り処を指定したのにファイルが無いなら報告する。指定は「そこを検査せよ」という
// 意思表示なので、黙って通すと検査が無効になったことに気づけない。
// 報告にはどちらの指定を直せばよいか (origin) を載せる — 解決の経路が 2 つあるため。
func TestJudgmentFlowAbsentFileReportedWhenOriginGiven(t *testing.T) {
	read := func(_ string) ([]byte, error) { return nil, fs.ErrNotExist }
	for _, origin := range []string{"-judgment-flow", "CLAUDE_PLUGIN_ROOT"} {
		t.Run(origin, func(t *testing.T) {
			problems := judgmentFlowProblems(nil, read, origin)
			if len(problems) != 1 {
				t.Fatalf("指定したパスが不在なのに報告が 1 件でない: %v", problems)
			}
			if !strings.Contains(problems[0], origin) || !strings.Contains(problems[0], judgmentFlowPath) {
				t.Fatalf("報告に指定の出所 %q か対象のパスが無い: %q", origin, problems[0])
			}
		})
	}
}

// -write-judgment-flow は表から図を生成してフェンスの中身を置き換える。生成した後は
// 検査が通る (鮮度が保たれる)。
func TestWriteJudgmentFlowDiagram(t *testing.T) {
	path := filepath.Join(t.TempDir(), "judgment-flow.md")
	stale := strings.Replace(judgmentFlowFixture, judgmentFlowDiagram, "flowchart TD\n  D1{\"古い図\"}", 1)
	if err := os.WriteFile(path, []byte(stale), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := writeJudgmentFlowDiagram(path); err != nil {
		t.Fatalf("生成に失敗した: %v", err)
	}
	got, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != judgmentFlowFixture {
		t.Fatalf("生成した内容がフィクスチャと一致しない:\n%s", got)
	}
	if problems := judgmentFlowCheck(string(got)); len(problems) != 0 {
		t.Fatalf("生成した直後なのに問題が出た: %v", problems)
	}
}

// 表に問題があれば図を生成しない (壊れた表から生成した図を正本の隣に置かない)。
func TestWriteJudgmentFlowDiagramRefusesBrokenTables(t *testing.T) {
	path := filepath.Join(t.TempDir(), "judgment-flow.md")
	content := strings.Replace(judgmentFlowFixture, "| H1 | 人間が判断 | D2 |\n", "", 1)
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := writeJudgmentFlowDiagram(path); err == nil {
		t.Fatal("表が壊れているのに図を生成した")
	}
	got, _ := os.ReadFile(path)
	if string(got) != content {
		t.Fatal("生成を拒否したのにファイルが書き換わった")
	}
}

// -write-judgment-flow の経路: 在り処が無ければエラー、他の経路とは併用できない。
func TestRunWriteJudgmentFlowRoute(t *testing.T) {
	repo := realTempDir(t)
	recs := filepath.Join(repo, "docs", "rt")
	if err := os.MkdirAll(recs, 0o755); err != nil {
		t.Fatal(err)
	}
	flow := filepath.Join(repo, "judgment-flow.md")
	if err := os.WriteFile(flow, []byte(judgmentFlowFixture), 0o644); err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name    string
		args    []string
		wantErr bool
	}{
		{"生成できる", []string{"-record-dir", recs, "-judgment-flow", flow, "-write-judgment-flow"}, false},
		{"在り処が無い", []string{"-record-dir", recs, "-write-judgment-flow"}, true},
		{"-write-summary と併用", []string{"-record-dir", recs, "-judgment-flow", flow, "-write-judgment-flow", "-write-summary"}, true},
		{"-review-file と併用", []string{"-record-dir", recs, "-judgment-flow", flow, "-write-judgment-flow", "-review-file", flow}, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			withRunGlobals(t)
			err := run(tc.args)
			if tc.wantErr && err == nil {
				t.Fatal("エラーになるべき呼び出しが通った")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("通るべき呼び出しがエラーになった: %v", err)
			}
		})
	}
}
